#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# Values (incl. N8N_ENCRYPTION_KEY) live outside any repo, so a reboot or a
# deleted checkout can't lose them. Losing the encryption key = losing every
# credential saved in n8n.
ENV_FILE="$HOME/.config/oracle-n8n/.env"
mkdir -p "$(dirname "$ENV_FILE")"; chmod 700 "$(dirname "$ENV_FILE")"

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
HOST_ALIAS="oracle-n8n"

rssh() { ssh -i "$OCI_SSH_KEY" -o StrictHostKeyChecking=accept-new -o ConnectTimeout=15 "ubuntu@$OCI_PUBLIC_IP" "$@"; }
rscp() { scp -i "$OCI_SSH_KEY" -o StrictHostKeyChecking=accept-new -q "$@"; }

banner "Oracle Cloud Always Free VPS for n8n + Postgres/pgvector"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Oracle Cloud account + home region"
say "Create (or sign in to) an Oracle Cloud Free Tier account."
open_url "https://signup.cloud.oracle.com/"
step "Sign up with your email; a credit card is needed for identity verification (Always Free usage isn't charged)."
step "Pick the HOME REGION carefully: it can't be changed, and Always Free compute only runs there."
note "Nearby options: Singapore (ap-singapore-1), Jakarta (ap-batam-1 is Batam). If A1 capacity is"
note "often 'out of host capacity' in one region, that's common; retrying later usually works."
step "Wait for the welcome email saying the account is ready, then sign in."
say ""
say "The region identifier is shown in the console's top bar region menu (e.g. ap-singapore-1)."
ask OCI_REGION "Home region identifier:"
write_env OCI_REGION "$OCI_REGION"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Upgrade to Pay-As-You-Go + budget alert"
say "Free Tier accounts can lose an idle Always Free VM (CPU, network AND memory all under"
say "20% p95 for 7 days); the VM and its disk, backups included, are deleted. Pay-As-You-Go"
say "accounts aren't reclaimed, and Always Free resources stay free on them."
if [[ "$(_existing OCI_ACCOUNT_TYPE || true)" == "payg" ]]; then
  note "Already recorded as Pay-As-You-Go in $ENV_FILE; skipping the upgrade part."
else
  open_url "https://cloud.oracle.com/invoices-and-orders/upgrade-and-payment"
  note "Console labels move around; if the link lands elsewhere: menu → Billing & Cost Management"
  note "→ Upgrade and Manage Payment."
  step "Choose 'Upgrade your account' → Pay As You Go, confirm the card on file, submit."
  step "Wait for the 'upgrade complete' email (minutes to a few hours); the wizard can go on meanwhile."
  if confirm "Upgrade submitted (or already done)?"; then
    write_env OCI_ACCOUNT_TYPE payg
  else
    SKIPPED+=("Pay-As-You-Go upgrade (stage 2): the VM can be reclaimed while idle until this is done")
  fi
fi
say ""
say "Now a budget alert, so any accidental paid resource shows up in your inbox quickly."
open_url "https://cloud.oracle.com/usage/budgets?region=$OCI_REGION"
note "Or: menu → Billing & Cost Management → Budgets."
step "Create Budget → Name: monthly-guard · Target: Compartment (root) · Schedule: Monthly."
step "Budget amount: 1 (USD, or the smallest amount in your billing currency)."
step "Alert rule 1: Actual spend · 50% of budget · your email."
step "Alert rule 2: Forecast spend · 100% of budget · your email. Click Create."
warn "A budget alert only notifies; it never stops spending. Create only resources labelled"
warn "'Always Free-eligible', and keep A1 at 2 OCPU / 12 GB."
ask OCI_BUDGET_EMAIL "Email the alerts go to (for your records):"
write_env OCI_BUDGET_EMAIL "$OCI_BUDGET_EMAIL"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "SSH key for the server"
OCI_SSH_KEY="$HOME/.ssh/id_ed25519_oracle"
if [[ -f "$OCI_SSH_KEY" ]]; then
  say "Reusing existing key $OCI_SSH_KEY"
else
  say "A dedicated key keeps this server separate from your other keys."
  if confirm "Create $OCI_SSH_KEY now? (ssh-keygen will ask for an optional passphrase)"; then
    ssh-keygen -t ed25519 -f "$OCI_SSH_KEY" -C "oracle-n8n"
  else
    ask OCI_SSH_KEY "Path to the private key you want to use instead:"
  fi
fi
write_env OCI_SSH_KEY "$OCI_SSH_KEY"
say ""
say "Public key (you'll paste this in the next stage):"
printf '\n%s\n\n' "$(cat "$OCI_SSH_KEY.pub")"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Create the Ampere A1 instance"
open_url "https://cloud.oracle.com/compute/instances?region=$OCI_REGION"
note "Console labels move around between releases; follow the meaning if a name differs slightly."
step "Click 'Create instance'. Name: n8n. Compartment: root is fine."
step "Image and shape → Change image → Canonical Ubuntu → 24.04 (NOT 'Minimal')."
step "Change shape → Ampere → VM.Standard.A1.Flex → 2 OCPUs, 12 GB memory (the Always Free max)."
step "Check it shows the 'Always Free-eligible' label."
step "Networking: create a new VCN + new public subnet; keep 'Assign a public IPv4 address' ON."
step "Add SSH keys → 'Paste public keys' → paste the key shown in stage 3 (printed again below)."
step "Boot volume: 'Specify a custom size' → 100 GB (free total is 200 GB boot + block)."
step "Click Create. 'Out of host capacity'? Try another availability domain, or retry later."
step "Wait until the state is RUNNING, then copy 'Public IPv4 address' from the instance details."
printf '\n%s\n\n' "$(cat "$OCI_SSH_KEY.pub")"
note "Leave the default security list as is: only port 22 (SSH) is open, which is all we need."
while :; do
  ask OCI_PUBLIC_IP "Public IPv4 address:"
  [[ "$OCI_PUBLIC_IP" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ ]] && break
  warn "That doesn't look like an IPv4 address, try again."
done
write_env OCI_PUBLIC_IP "$OCI_PUBLIC_IP"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Connect over SSH"
say "Testing ssh ubuntu@$OCI_PUBLIC_IP (the first boot can take a minute or two)…"
until rssh true; do
  warn "SSH failed. Is the instance RUNNING and was the right public key pasted?"
  confirm "Retry?" || { warn "Stopping here; re-run the wizard once SSH works."; exit 1; }
done
printf '  %s✓ SSH works%s\n' "$GREEN" "$RESET"
if grep -qE "^Host[[:space:]]+$HOST_ALIAS\$" "$HOME/.ssh/config" 2>/dev/null; then
  note "~/.ssh/config already has 'Host $HOST_ALIAS'; check its HostName matches $OCI_PUBLIC_IP."
elif confirm "Add 'Host $HOST_ALIAS' to ~/.ssh/config so you can type 'ssh $HOST_ALIAS'?"; then
  printf '\nHost %s\n  HostName %s\n  User ubuntu\n  IdentityFile %s\n  ServerAliveInterval 60\n' \
    "$HOST_ALIAS" "$OCI_PUBLIC_IP" "$OCI_SSH_KEY" >> "$HOME/.ssh/config"
  printf '  %s✓ added%s Host %s → ~/.ssh/config\n' "$GREEN" "$RESET" "$HOST_ALIAS"
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Server bootstrap: updates, Docker, swap"
say "This runs on the server: apt upgrade, install docker.io + docker-compose-v2,"
say "add 'ubuntu' to the docker group, create a 4 GB swap file, set timezone Asia/Jakarta."
if confirm "Run the bootstrap now? (takes a few minutes)"; then
  rssh 'bash -s' <<'EOF'
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
# A fresh VM runs cloud-init + unattended-upgrades on first boot, which hold
# the apt locks for a few minutes. Wait for them instead of failing.
echo "waiting for first-boot apt jobs to finish…"
sudo cloud-init status --wait >/dev/null 2>&1 || true
for _ in $(seq 1 120); do
  sudo fuser /var/lib/apt/lists/lock /var/lib/dpkg/lock /var/lib/dpkg/lock-frontend >/dev/null 2>&1 || break
  sleep 5
done
APT=(sudo apt-get -o DPkg::Lock::Timeout=600)
"${APT[@]}" update -q
"${APT[@]}" -y -q upgrade
"${APT[@]}" -y -q install docker.io docker-compose-v2
sudo systemctl enable --now docker
sudo usermod -aG docker ubuntu
if ! swapon --show | grep -q /swapfile; then
  sudo fallocate -l 4G /swapfile && sudo chmod 600 /swapfile
  sudo mkswap /swapfile && sudo swapon /swapfile
  grep -q '^/swapfile' /etc/fstab || echo '/swapfile none swap sw 0 0' | sudo tee -a /etc/fstab >/dev/null
fi
sudo timedatectl set-timezone Asia/Jakarta
docker --version; docker compose version
EOF
  printf '  %s✓ bootstrap done%s\n' "$GREEN" "$RESET"
  note "If the upgrade installed a new kernel, reboot later from the console or 'sudo reboot'."
else
  SKIPPED+=("server bootstrap (stage 6)")
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Deploy n8n + Postgres/pgvector"
# Never generate a second encryption key for an existing install: recover it first.
for k in N8N_ENCRYPTION_KEY POSTGRES_PASSWORD; do
  cur=$(_existing "$k" || true)
  if [[ -z "$cur" ]]; then
    cur=$(rssh "grep -E '^$k=' ~/n8n/.env 2>/dev/null | cut -d= -f2-" || true)
    [[ -n "$cur" ]] && note "recovered $k from the server's ~/n8n/.env"
  fi
  [[ -z "$cur" ]] && cur=$(openssl rand -hex 32)
  write_env "$k" "$cur"
done

say "Uploads this repo's stack/ (docker-compose.yml, init/, backup.sh) plus a generated .env to ~/n8n."
note "Images are pinned in stack/docker-compose.yml; both ports bind to 127.0.0.1 only."
if confirm "Upload and start the stack?"; then
  "$REPO_DIR/scripts/deploy.sh"
  rssh '(crontab -l 2>/dev/null | grep -v n8n/backup.sh; echo "0 2 * * * $HOME/n8n/backup.sh >/dev/null 2>&1") | crontab -'
  say "Waiting for n8n to answer on the server…"
  ok=0
  for _ in $(seq 1 30); do
    if rssh 'curl -fs http://127.0.0.1:5678/healthz >/dev/null'; then ok=1; break; fi
    sleep 5
  done
  if (( ok )); then printf '  %s✓ n8n is up%s\n' "$GREEN" "$RESET"
  else warn "n8n didn't answer yet; check: ssh $HOST_ALIAS 'cd ~/n8n && docker compose logs --tail 50 n8n'"; fi
  rssh "docker compose -f ~/n8n/docker-compose.yml exec -T postgres psql -U n8n -d knowledge -tAc \"select 'pgvector ' || extversion from pg_extension where extname='vector'\"" || true
  printf '  %s✓ daily backup%s 02:00 → ~/backups on the server\n' "$GREEN" "$RESET"
else
  SKIPPED+=("deploy stack (stage 7): run scripts/deploy.sh later")
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Back up the encryption key"
say "n8n encrypts every saved credential with N8N_ENCRYPTION_KEY. A database backup without"
say "this key can't be restored, and the only copies are $ENV_FILE and ~/n8n/.env on the VPS."
if [[ "$(_existing SECRETS_BACKED_UP || true)" == "yes" ]]; then
  note "Already confirmed backed up in an earlier run."
elif [[ -z "${N8N_ENCRYPTION_KEY:-}" ]]; then
  warn "No N8N_ENCRYPTION_KEY yet (stage 7 skipped?); re-run the wizard after deploying."
  SKIPPED+=("encryption key backup (stage 8)")
else
  step "In your password manager (Google Password Manager, Bitwarden, …) add an entry 'oracle-n8n'."
  note "Google: passwords.google.com → Add · Site oracle-n8n.local · Username n8n ·"
  note "Password = N8N_ENCRYPTION_KEY · Note = the other values below."
  step "Store these values in it (shown once; the screen clears on the next stage):"
  printf '\n    %sN8N_ENCRYPTION_KEY%s=%s\n    %sPOSTGRES_PASSWORD%s=%s\n' \
    "$BOLD" "$RESET" "$N8N_ENCRYPTION_KEY" "$BOLD" "$RESET" "$POSTGRES_PASSWORD"
  printf '    %sOCI_PUBLIC_IP%s=%s    %sOCI_REGION%s=%s\n\n' \
    "$BOLD" "$RESET" "$OCI_PUBLIC_IP" "$BOLD" "$RESET" "$OCI_REGION"
  step "Also attach the SSH private key $OCI_SSH_KEY (or keep a copy somewhere other than this PC)."
  pause "Saved? Press Enter, then paste the key back FROM the password manager to verify."
  while :; do
    check=""
    ask_secret check "N8N_ENCRYPTION_KEY from the password manager:" || check=""
    if [[ "$check" == "$N8N_ENCRYPTION_KEY" ]]; then
      printf '  %s✓ key backup verified%s\n' "$GREEN" "$RESET"
      write_env SECRETS_BACKED_UP yes
      break
    fi
    warn "That doesn't match the key in $ENV_FILE (extra spaces? partial copy?)."
    confirm "Try again?" || { SKIPPED+=("encryption key backup (stage 8): not verified"); break; }
  done
fi
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Open n8n through the SSH tunnel"
say "n8n isn't exposed to the internet. To use it, run this on your machine:"
printf '\n    %sssh -N -L 5678:localhost:5678 -L 5432:localhost:5432 -i %s ubuntu@%s%s\n\n' \
  "$BOLD" "$OCI_SSH_KEY" "$OCI_PUBLIC_IP" "$RESET"
note "(5432 is the knowledge Postgres for the ingest script; drop that -L if you only need n8n.)"
if confirm "Start the tunnel in the background now?"; then
  ssh -f -N -L 5678:localhost:5678 -L 5432:localhost:5432 -i "$OCI_SSH_KEY" "ubuntu@$OCI_PUBLIC_IP" \
    && printf '  %s✓ tunnel running%s (stop it later with: pkill -f "5678:localhost:5678")\n' "$GREEN" "$RESET"
fi
open_url "http://localhost:5678"
step "Create the n8n owner account (email + strong password; store it in your password manager)."
step "Gmail OAuth later: use the callback URL n8n shows (http://localhost:5678/...); Google accepts localhost."
say ""
if [[ "$(_existing OCI_ACCOUNT_TYPE || true)" != "payg" ]]; then
  warn "Account not recorded as Pay-As-You-Go: an idle VM can still be reclaimed. Finish stage 2."
fi
if [[ "$(_existing SECRETS_BACKED_UP || true)" != "yes" ]]; then
  warn "N8N_ENCRYPTION_KEY isn't backed up yet: without it n8n credentials can't be restored. Finish stage 8."
fi
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
